function prepareArtifact(){
  const build=spawnSync(process.execPath,['scripts/build-hosting.js','production','paid-sync-preview'],{cwd:root,encoding:'utf8',stdio:'inherit'});
  if(build.status!==0)throw new Error('Paid Sync browser artifact build failed');
  const firebaseFiles=['firebase-app-compat.js','firebase-auth-compat.js','firebase-firestore-compat.js','firebase-storage-compat.js','firebase-app-check-compat.js'];
  const vendor=path.join(artifact,'vendor','firebase');fs.mkdirSync(vendor,{recursive:true});
  for(const file of firebaseFiles)fs.copyFileSync(path.join(root,'node_modules','firebase',file),path.join(vendor,file));
  const htmlPath=path.join(artifact,'index.html');let html=fs.readFileSync(htmlPath,'utf8');
  for(const file of firebaseFiles)html=html.replace(new RegExp(`https://www\\.gstatic\\.com/firebasejs/[^"']+/${file}`,'g'),`vendor/firebase/${file}`);
  html=html.replace(/<script[^>]+https:\/\/(?:cdnjs\.cloudflare\.com|js-de\.sentry-cdn\.com)[\s\S]*?<\/script>\s*/gi,'');
  html=html.replace(/<link[^>]+https:\/\/fonts\.(?:googleapis|gstatic)\.com[^>]*>\s*/gi,'');
  html=html.replace(/<noscript><link[^>]+https:\/\/fonts\.googleapis\.com[^>]*><\/noscript>\s*/gi,'');
  fs.writeFileSync(htmlPath,html);
  fs.writeFileSync(path.join(artifact,'src','app','sentry-bootstrap.js'),"'use strict';\nwindow.sentryOnLoad=function(){};\n");
  fs.writeFileSync(path.join(artifact,'firebase-environment.js'),`'use strict';\nwindow.TAXMATE_FIREBASE_ENVIRONMENT=Object.freeze({firebaseConfig:Object.freeze({apiKey:'demo-api-key',authDomain:'demo-taxmate.firebaseapp.com',projectId:'demo-taxmate',storageBucket:'demo-taxmate.appspot.com',messagingSenderId:'100000000000',appId:'1:100000000000:web:paid-sync'}),hosts:Object.freeze(['127.0.0.1','localhost']),appCheckKey:'demo-only'});\n(function(){const init=firebase.initializeApp.bind(firebase);firebase.initializeApp=function(config,name){const app=init(config,name);firebase.auth(app).useEmulator('http://127.0.0.1:${emulatorPorts.auth}',{disableWarnings:true});firebase.firestore(app).useEmulator('127.0.0.1',${emulatorPorts.firestore});firebase.storage(app).useEmulator('127.0.0.1',${emulatorPorts.storage});return app;};firebase.appCheck=function(){return{activate:function(){},getToken:async function(){return{token:'emulator-app-check'};}};};})();\n`);
  if(/taxmate-uk-2/.test(fs.readFileSync(path.join(artifact,'firebase-environment.js'),'utf8')))throw new Error('Production provider leaked into Paid Sync harness');
}
