  server=http.createServer((req,res)=>{const pathname=new URL(req.url,'http://127.0.0.1').pathname;let relative=decodeURIComponent(pathname==='/'?'/index.html':pathname).replace(/^\/+/, '');const target=path.resolve(artifact,relative);if(!target.startsWith(path.resolve(artifact)+path.sep)||!fs.existsSync(target)){res.writeHead(404);res.end('Not found');return;}res.writeHead(200,{'Content-Type':mime[path.extname(target)]||'application/octet-stream','Cache-Control':'no-store'});fs.createReadStream(target).pipe(res);});
